--
-- Table structure for table `cycle_records`
--

DROP TABLE IF EXISTS `cycle_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cycle_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `job_order_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `cycle_type` enum('wash','dry','fold','iron') NOT NULL,
  `machine_number` int(10) unsigned DEFAULT NULL,
  `cycle_number` int(10) unsigned NOT NULL DEFAULT 1,
  `started_at` timestamp NULL DEFAULT NULL,
  `ended_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `cycle_records_job_order_id_foreign` (`job_order_id`),
  KEY `cycle_records_user_id_foreign` (`user_id`),
  KEY `cycle_records_active_machine_index` (`cycle_type`,`machine_number`,`ended_at`),
  KEY `cycle_records_activity_index` (`started_at`,`cycle_type`,`machine_number`,`job_order_id`),
  KEY `cycle_records_order_history_index` (`job_order_id`,`started_at`,`id`),
  CONSTRAINT `cycle_records_job_order_id_foreign` FOREIGN KEY (`job_order_id`) REFERENCES `job_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cycle_records_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=775 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

