--
-- Table structure for table `daily_task_completions`
--

DROP TABLE IF EXISTS `daily_task_completions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `daily_task_completions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `daily_task_id` bigint(20) unsigned NOT NULL,
  `branch_id` bigint(20) unsigned NOT NULL,
  `completed_by` bigint(20) unsigned DEFAULT NULL,
  `completed_by_employee_id` bigint(20) unsigned DEFAULT NULL,
  `work_date` date NOT NULL,
  `photo_path` varchar(255) NOT NULL,
  `remarks` text DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `daily_task_branch_date_unique` (`daily_task_id`,`branch_id`,`work_date`),
  KEY `daily_task_completions_branch_id_foreign` (`branch_id`),
  KEY `daily_task_completions_completed_by_foreign` (`completed_by`),
  KEY `daily_task_completions_completed_by_employee_id_foreign` (`completed_by_employee_id`),
  CONSTRAINT `daily_task_completions_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `daily_task_completions_completed_by_employee_id_foreign` FOREIGN KEY (`completed_by_employee_id`) REFERENCES `attendance_employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `daily_task_completions_completed_by_foreign` FOREIGN KEY (`completed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `daily_task_completions_daily_task_id_foreign` FOREIGN KEY (`daily_task_id`) REFERENCES `daily_tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

