--
-- Table structure for table `job_orders`
--

DROP TABLE IF EXISTS `job_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `job_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `branch_id` bigint(20) unsigned NOT NULL,
  `processing_branch_id` bigint(20) unsigned DEFAULT NULL,
  `current_branch_id` bigint(20) unsigned DEFAULT NULL,
  `release_branch_id` bigint(20) unsigned DEFAULT NULL,
  `customer_id` bigint(20) unsigned NOT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `job_order_number` varchar(255) NOT NULL,
  `status` enum('pending','washing','drying','folding','ready_for_pickup','ready_for_delivery','completed','cancelled') NOT NULL DEFAULT 'pending',
  `transaction_type` varchar(255) NOT NULL DEFAULT 'walk_in',
  `is_rush` tinyint(1) NOT NULL DEFAULT 0,
  `subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `tax` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `balance` decimal(12,2) NOT NULL DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `production_completed_at` timestamp NULL DEFAULT NULL,
  `production_accepted_at` timestamp NULL DEFAULT NULL,
  `inventory_deducted_at` timestamp NULL DEFAULT NULL,
  `returned_to_branch_at` timestamp NULL DEFAULT NULL,
  `released_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `job_orders_job_order_number_unique` (`job_order_number`),
  KEY `job_orders_customer_id_foreign` (`customer_id`),
  KEY `job_orders_created_by_foreign` (`created_by`),
  KEY `job_orders_branch_id_status_index` (`branch_id`,`status`),
  KEY `job_orders_status_created_index` (`status`,`created_at`),
  KEY `job_orders_customer_status_index` (`customer_id`,`status`),
  KEY `job_orders_processing_status_index` (`processing_branch_id`,`status`),
  KEY `job_orders_current_status_index` (`current_branch_id`,`status`),
  KEY `job_orders_release_status_index` (`release_branch_id`,`status`),
  KEY `job_orders_is_rush_index` (`is_rush`),
  CONSTRAINT `job_orders_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `job_orders_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_orders_current_branch_id_foreign` FOREIGN KEY (`current_branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_orders_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `job_orders_processing_branch_id_foreign` FOREIGN KEY (`processing_branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_orders_release_branch_id_foreign` FOREIGN KEY (`release_branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=202 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

