INSERT INTO `system_settings` VALUES (1,'SPIN KLEAN LAUNDRY','settings/vtJB21dr5tBOIOUgn9O5O9VmI8WVfGD4qDktwihM.png','eajwebdev@example.test','09170000000','Main Office','Thank you','Come again','PHP',0,0.00,'{\"monday\":{\"open\":\"08:00\",\"close\":\"18:00\"},\"tuesday\":{\"open\":\"08:00\",\"close\":\"18:00\"},\"wednesday\":{\"open\":\"08:00\",\"close\":\"18:00\"},\"thursday\":{\"open\":\"08:00\",\"close\":\"18:00\"},\"friday\":{\"open\":\"08:00\",\"close\":\"18:00\"},\"saturday\":{\"open\":\"08:00\",\"close\":\"18:00\"},\"sunday\":{\"open\":\"08:00\",\"close\":\"18:00\"}}',60.00,180.00,20.00,'JO','INV','unisms','sk_4dd34141-04fe-4ebe-8c4e-0dd26ae5a356','SpinKleans',NULL,NULL,NULL,NULL,0,'Dear {name}, your laundry order #{order_no} has been COMPLETED. Total: {price}, Balance: {balance}. You may pay online via https://spinklean.online/pay. Thank you for choosing {store}! We appreciate your business.','Dear {name}, your laundry order #{order_no} is now READY AND OUT FOR DELIVERY. Remaining balance: {balance}. You may pay online via https://spinklean.online/pay. Thank you for choosing {store}!','Dear {name}, your laundry order #{order_no} is now READY FOR PICKUP at {branch}. Remaining balance: {balance}. You may pay online via https://spinklean.online/pay. Please present your order number upon pickup. Thank you!','Dear {name}, thank you for choosing {store}. We have picked up your laundry order #{order_no} ({branch}) for a total of {price}. You may pay online via https://spinklean.online/pay. We will notify you once it is ready for delivery.','Dear {name}, thank you for choosing {store}. We have received your laundry order #{order_no} at {branch} for a total of {price}. You may pay online via https://spinklean.online/pay. We will notify you once your order is ready.','#08badd',0,1,0,NULL,NULL,'2026-05-12 05:49:07','2026-07-25 14:48:36');
