DROP TABLE IF EXISTS `z_readings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `z_readings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `branch_id` bigint(20) unsigned NOT NULL,
  `prepared_by` bigint(20) unsigned DEFAULT NULL,
  `reading_number` varchar(255) NOT NULL,
  `business_date` date NOT NULL,
  `cash_count` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`cash_count`)),
  `payment_breakdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`payment_breakdown`)),
  `expense_breakdown` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`expense_breakdown`)),
  `machine_counters` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`machine_counters`)),
  `expected_cash_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `cash_expense_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `expected_cash_drawer_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `actual_cash_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `expected_gcash_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `actual_gcash_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `expected_bank_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `actual_bank_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `expected_total_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `actual_total_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `over_short_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `transaction_count` int(10) unsigned NOT NULL DEFAULT 0,
  `first_job_order_number` varchar(255) DEFAULT NULL,
  `last_job_order_number` varchar(255) DEFAULT NULL,
  `signature_name` varchar(255) NOT NULL,
  `remarks` text DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `z_reading_branch_date_unique` (`branch_id`,`business_date`),
  UNIQUE KEY `z_readings_reading_number_unique` (`reading_number`),
  KEY `z_readings_prepared_by_foreign` (`prepared_by`),
  KEY `z_readings_business_date_branch_id_index` (`business_date`,`branch_id`),
  CONSTRAINT `z_readings_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `z_readings_prepared_by_foreign` FOREIGN KEY (`prepared_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

